using Npgsql; using NpgsqlTypes;
using SCOPX.Infrastructure.Audit;
namespace SCOPX.Infrastructure.Procedures;
public sealed class NpgsqlProcedureRepository(string connectionString) : IProcedureRepository
{
 private static async Task SetTenant(NpgsqlConnection c,NpgsqlTransaction t,Guid h,CancellationToken ct){await using var cmd=new NpgsqlCommand("SELECT set_config('scopx.hospital_id', @h, true)",c,t);cmd.Parameters.AddWithValue("h",NpgsqlDbType.Text,h.ToString());await cmd.ExecuteNonQueryAsync(ct);}
 private const string Columns="id,hospital_id,patient_id,procedure_type,scheduled_at,started_at,ended_at,status,room_label,clinical_indication,findings,impression,created_at,updated_at";
 private static ProcedureRecord Read(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetGuid(1),r.GetGuid(2),r.GetString(3),r.IsDBNull(4)?null:r.GetFieldValue<DateTimeOffset>(4),r.IsDBNull(5)?null:r.GetFieldValue<DateTimeOffset>(5),r.IsDBNull(6)?null:r.GetFieldValue<DateTimeOffset>(6),r.GetString(7),r.IsDBNull(8)?null:r.GetString(8),r.IsDBNull(9)?null:r.GetString(9),r.IsDBNull(10)?null:r.GetString(10),r.IsDBNull(11)?null:r.GetString(11),r.GetFieldValue<DateTimeOffset>(12),r.GetFieldValue<DateTimeOffset>(13));
 public async Task<IReadOnlyList<ProcedureRecord>> ListForPatientAsync(Guid h,Guid actorUserId,Guid p,CancellationToken ct=default){await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand($"SELECT {Columns} FROM procedures WHERE hospital_id=@h AND patient_id=@p ORDER BY COALESCE(scheduled_at,created_at) DESC LIMIT 250",c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("p",p);await using var r=await cmd.ExecuteReaderAsync(ct);var list=new List<ProcedureRecord>();while(await r.ReadAsync(ct))list.Add(Read(r));await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"procedure.listed","procedure_collection",p,new{result_count=list.Count},ct);await t.CommitAsync(ct);return list;}
 public async Task<ProcedureRecord?> GetAsync(Guid h,Guid actorUserId,Guid id,CancellationToken ct=default){await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand($"SELECT {Columns} FROM procedures WHERE hospital_id=@h AND id=@id LIMIT 1",c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("id",id);await using var r=await cmd.ExecuteReaderAsync(ct);ProcedureRecord? result=await r.ReadAsync(ct)?Read(r):null;await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"procedure.read","procedure",id,new{found=result is not null},ct);await t.CommitAsync(ct);return result;}
 public async Task<ProcedureRecord?> CreateAsync(Guid h,Guid actorUserId,ProcedureCreateRequest x,CancellationToken ct=default){const string sql="INSERT INTO procedures(hospital_id,patient_id,procedure_type,scheduled_at,room_label,clinical_indication) VALUES(@h,@p,@type,@scheduled,@room,@indication) RETURNING id";await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand(sql,c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("p",x.PatientId);cmd.Parameters.AddWithValue("type",x.ProcedureType.Trim());cmd.Parameters.AddWithValue("scheduled",NpgsqlDbType.TimestampTz,(object?)x.ScheduledAt?.UtcDateTime??DBNull.Value);cmd.Parameters.AddWithValue("room",NpgsqlDbType.Varchar,(object?)x.RoomLabel??DBNull.Value);cmd.Parameters.AddWithValue("indication",NpgsqlDbType.Text,(object?)x.ClinicalIndication??DBNull.Value);var id=(Guid)(await cmd.ExecuteScalarAsync(ct)??throw new InvalidOperationException("Procedure insert returned no ID"));
 await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"procedure.created","procedure",id,new{operation="create"},ct);
 await t.CommitAsync(ct);return await GetAsync(h,actorUserId,id,ct);}
 public async Task<bool> StartAsync(Guid h,Guid actorUserId,Guid id,DateTimeOffset at,CancellationToken ct=default){const string sql="UPDATE procedures SET status='in_progress',started_at=@at,updated_at=now() WHERE hospital_id=@h AND id=@id AND status='scheduled' AND started_at IS NULL";await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand(sql,c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("at",NpgsqlDbType.TimestampTz,at.UtcDateTime);var n=await cmd.ExecuteNonQueryAsync(ct);if(n==1)await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"procedure.started","procedure",id,new{operation="start"},ct);await t.CommitAsync(ct);return n==1;}
 public async Task<bool> CompleteAsync(Guid h,Guid actorUserId,Guid id,DateTimeOffset at,string? findings,string? impression,CancellationToken ct=default){const string sql="UPDATE procedures SET status='completed',ended_at=@at,findings=@findings,impression=@impression,updated_at=now() WHERE hospital_id=@h AND id=@id AND status='in_progress' AND started_at IS NOT NULL AND @at>=started_at";await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand(sql,c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("at",NpgsqlDbType.TimestampTz,at.UtcDateTime);cmd.Parameters.AddWithValue("findings",NpgsqlDbType.Text,(object?)findings??DBNull.Value);cmd.Parameters.AddWithValue("impression",NpgsqlDbType.Text,(object?)impression??DBNull.Value);var n=await cmd.ExecuteNonQueryAsync(ct);if(n==1)await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"procedure.completed","procedure",id,new{operation="complete"},ct);await t.CommitAsync(ct);return n==1;}
}
